import{_ as t}from"./chunks/routines-view.5aZhkrIx.js";import{_ as r,H as s,f as n,i as o}from"./chunks/framework.CSxcEb-0.js";const m=JSON.parse('{"title":"Routines","description":"","frontmatter":{},"headers":[],"relativePath":"guide/routines.md","filePath":"guide/routines.md"}'),a={name:"guide/routines.md"};function i(d,e,l,u,c,h){return s(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="routines" tabindex="-1">Routines <a class="header-anchor" href="#routines" aria-label="Permalink to &quot;Routines&quot;">​</a></h1><p><strong>Routines</strong> are recurring protected-time patterns — separate from one-off <strong>tasks</strong> and fixed <strong>events</strong>.</p><p><img src="'+t+'" alt="Routines view"></p><h2 id="routines-vs-tasks-vs-events" tabindex="-1">Routines vs tasks vs events <a class="header-anchor" href="#routines-vs-tasks-vs-events" aria-label="Permalink to &quot;Routines vs tasks vs events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>Use for</th></tr></thead><tbody><tr><td><strong>Tasks</strong></td><td>Actionable work with due dates, duration, priorities, dependencies, splittable scheduling</td></tr><tr><td><strong>Events</strong></td><td>Time blocks that reserve calendar time and act as busy constraints for the scheduler</td></tr><tr><td><strong>Routines</strong></td><td>Repeated structures: morning planning, workouts, deep-work windows, weekly reviews</td></tr></tbody></table><h2 id="when-to-use-routines" tabindex="-1">When to use routines <a class="header-anchor" href="#when-to-use-routines" aria-label="Permalink to &quot;When to use routines&quot;">​</a></h2><p>Use routines when the time pattern repeats (daily, weekly, monthly style cadence) and you want protected structure on the timeline without treating each occurrence as a separate task to complete.</p><p>Use <strong>tasks</strong> when you need due dates, completion, and splitting around meetings.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><p>Routines can participate in the same <strong>dependency</strong> links as tasks. In the routine editor, use <strong>Depends on</strong> to wait until other tasks or routines finish, and <strong>Blocks</strong> to list items that must wait for this routine.</p><ul><li>The scheduler orders routines and tasks together; cycles are rejected.</li><li>A routine that <strong>depends on</strong> another item: each scheduled occurrence starts only after that prerequisite’s end time for the current reschedule pass.</li><li>A <strong>task that depends on</strong> a repeating routine waits until the <strong>first</strong> scheduled occurrence in the horizon finishes (same rule as other repeating prerequisites). For “after today’s lunch, do X,” set the task to depend on the <strong>Lunch</strong> routine.</li></ul><p>See <a href="./tasks#dependencies">Tasks — Dependencies</a> for drop-to-link behavior in list views (tasks only; link routines in the editor).</p><h2 id="creating-routines" tabindex="-1">Creating routines <a class="header-anchor" href="#creating-routines" aria-label="Permalink to &quot;Creating routines&quot;">​</a></h2><p>Open <strong>Routines</strong> from the sidebar, pick a preset, or use <strong>New</strong> to open the editor. Set title, duration, repeat cadence, and when the routine should land on your calendar.</p><h3 id="subroutines-advanced" tabindex="-1">Subroutines (advanced) <a class="header-anchor" href="#subroutines-advanced" aria-label="Permalink to &quot;Subroutines (advanced)&quot;">​</a></h3><p>Off by default. Turn on <strong>Subroutines (advanced)</strong> in <strong>Settings → Scheduler</strong> to nest routines under a parent in the Routines view. Drag to reorder or reparent. Each routine still schedules independently; nesting is for organization only.</p><h3 id="smart-editor-layout" tabindex="-1">Smart editor layout <a class="header-anchor" href="#smart-editor-layout" aria-label="Permalink to &quot;Smart editor layout&quot;">​</a></h3><p>Routine editing uses the same <strong>Smart task editor</strong> behavior as tasks (see <a href="./tasks#smart-editor-layout-primary-vs-more-options">Tasks — Smart editor layout</a>): preset, duration, time window, scheduling profile, and repeats stay easy to reach; less-used fields (flexible duration, notes, list) may move under <strong>More options</strong> based on your saved routines. Override in <strong>Settings → Scheduler</strong>.</p><h3 id="time-window-clock" tabindex="-1">Time window (clock) <a class="header-anchor" href="#time-window-clock" aria-label="Permalink to &quot;Time window (clock)&quot;">​</a></h3><p>The routine editor uses a <strong>clock dial</strong> instead of separate time fields:</p><ul><li>Drag the <strong>arc ends</strong> to set the allowed <strong>window start</strong> and <strong>window end</strong> (overnight windows, e.g. sleep, wrap past midnight on the dial).</li><li>Drag the <strong>inner dot</strong> for <strong>preferred start</strong> — where TemPad tries to place the block inside the window.</li><li>A summary line under the dial shows the exact times (e.g. <code>11:30 AM – 1:30 PM · prefers 12:15 PM</code>).</li><li><strong>Scheduling profile</strong> chooses which weekdays apply (chips under the dial mirror enabled days). Change profile day boundaries in <strong>Settings → Scheduling hours</strong>.</li></ul><h3 id="reschedule-delay-routines" tabindex="-1">Reschedule delay (routines) <a class="header-anchor" href="#reschedule-delay-routines" aria-label="Permalink to &quot;Reschedule delay (routines)&quot;">​</a></h3><p>In <strong>Settings → Scheduler</strong>, <strong>Reschedule delay (routines)</strong> can be longer than the task delay (or <strong>Same as tasks</strong>). Routine saves debounce separately but still trigger a single scheduler pass when the timer fires. Use <strong>Reschedule</strong> on the Calendar for an immediate run (including meal spacing).</p><h3 id="meal-spacing" tabindex="-1">Meal spacing <a class="header-anchor" href="#meal-spacing" aria-label="Permalink to &quot;Meal spacing&quot;">​</a></h3><p>On the next <strong>Reschedule</strong> pass (auto or manual), TemPad spreads multiple <strong>meal</strong> routines across the same day if their titles match: <code>breakfast</code>, <code>lunch</code>, <code>dinner</code>, <code>meal</code>, or <code>snack</code> (case-insensitive). Each routine keeps its own window; TemPad picks preferred start times with at least <strong>2 hours</strong> between meals when possible.</p><p>Example: create daily routines named <strong>Breakfast</strong>, <strong>Lunch</strong>, and <strong>Dinner</strong>, then <strong>Reschedule</strong> — blocks should spread through the day instead of stacking at one preferred time.</p><p>If windows are too tight to honor spacing, TemPad keeps your saved preferred times and may show a scheduling note for that day.</p><h3 id="deleting-routine-occurrences" tabindex="-1">Deleting routine occurrences <a class="header-anchor" href="#deleting-routine-occurrences" aria-label="Permalink to &quot;Deleting routine occurrences&quot;">​</a></h3><p>From the <strong>calendar</strong>, open a routine block and choose <strong>Delete</strong> to remove <strong>this occurrence</strong>, <strong>this and following</strong>, or <strong>all occurrences</strong> (same as repeating events). Routines are not marked complete per occurrence; excluded occurrences simply stop appearing after the next <strong>Reschedule</strong>.</p><p>For one-off meetings or appointments that should block scheduling, prefer <strong>events</strong> (from Calendar or task/event editor) or <strong>Google Calendar</strong> imports.</p>',30)])])}const f=r(a,[["render",i]]);export{m as __pageData,f as default};
